(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["microbiology-exam-1-transmission-of-microorganisms-quiz"]={"title":"Transmission of Microorganisms — Quiz 1","category":"Microbiology","exam":"Exam 1","sem":"fall-2026","questions":[{"q":"Which mechanism requires a bacteriophage acting as a vector?","choices":["Transduction","Conjugation","Transformation","Binary fission"],"answer":0,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 45"},{"q":"What is a biofilm?","choices":["A single-species colony on an agar plate","A protective coating applied to hospital surfaces","A layer of dead cells with no clinical effect","A resistant polymicrobial network"],"answer":3,"exp":"Correct — Staphylococcus and Pseudomonas produce them. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 38"},{"q":"What does HORIZONTAL transmission usually involve?","choices":["Mother to child","Contaminated drinking water","A mosquito bite","Mucous membrane contact"],"answer":3,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 17"},{"q":"Which illness is the commonest consequence of FOOD as a transmission vehicle?","choices":["Gastrointestinal illness","Respiratory illness","Skin infection","Central nervous system infection"],"answer":0,"exp":"Correct — hence food safety and quality. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 18"},{"q":"Which consequence of hospital-acquired infection is named?","choices":["Longer hospital stays and preventable deaths","Shorter admissions from earlier discharge","Reduced treatment cost","Improved quality of care"],"answer":0,"exp":"Correct — with long-term disability and expense. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 19"},{"q":"In diseases such as plague and anthrax, what role do humans usually play?","choices":["The accidental host","The primary host","The definitive host","The vector"],"answer":0,"exp":"Correct — the lifecycle runs through primary and secondary hosts. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 6"},{"q":"Which of the following is a NON-LIVING reservoir of infection?","choices":["Humans","Animals","Plants","Soil"],"answer":3,"exp":"Correct — with water, air, food and fomites. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 4"},{"q":"How many links does the chain of infection have?","choices":["Three","Four","Eight","Six"],"answer":3,"exp":"Correct: agent, reservoir, portal of exit, mode of transmission, portal of entry, susceptible host. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 3"},{"q":"Which resistant organism was cultured from peripheral computer devices?","choices":["Plasmodium falciparum","Clostridioides difficile","MRSA","Mycobacterium tuberculosis"],"answer":2,"exp":"Correct — methicillin-resistant Staphylococcus aureus, alongside coliforms. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 31"},{"q":"Which practice did Semmelweis introduce in the 1840s?","choices":["Antibiotic prophylaxis","Handwashing with chlorine","Handwashing with carbolic acid","Sterile surgical gloves"],"answer":1,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 37"},{"q":"Which link does the chain of infection end with?","choices":["The reservoir","The mode of transmission","A susceptible host","The portal of entry"],"answer":2,"exp":"Correct — and susceptibility varies between hosts. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 3"},{"q":"Which zoonosis is the commonest in the UNITED STATES?","choices":["Plague","Rabies","Malaria","Ebola"],"answer":1,"exp":"Correct. Malaria leads worldwide, but is barely endemic in the United States. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 8"},{"q":"Which practice was named as a risk factor for contaminating antiseptics?","choices":["Refrigerating the product","Using single-use sachets","Labelling containers with dates","Topping up containers"],"answer":3,"exp":"Correct — with recycled bottles and inconsistent preparation. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 41"},{"q":"Airborne transmission is described as usually being what kind of phenomenon?","choices":["A seasonal one only","An indoor one","An outdoor one","A tropical one"],"answer":1,"exp":"Correct — though not always. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 18"},{"q":"Roughly what share of human infections do viruses cause, according to the Boone and Gerba review?","choices":["About twenty-five per cent","About sixty per cent","About ten per cent","About ninety per cent"],"answer":1,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 32"},{"q":"Which product category was most often contaminated in the West African hospital study?","choices":["Alcohol hand rub","Surgical scrub brushes","Liquid soap","Bar soap"],"answer":2,"exp":"Correct — 51 of 69 samples. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 41"},{"q":"What distinguishes INDIRECT contact transmission?","choices":["It requires an insect vector","It only occurs in hospitals","It only involves respiratory droplets","A surface comes between them"],"answer":3,"exp":"Correct — that is fomite transmission. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 17"},{"q":"Which is the FIRST of the suggested best practices for disinfecting non-critical surfaces?","choices":["Monitor compliance with feedback","Implement no-touch decontamination technology","Educate all staff","Standardise cleaning policy"],"answer":3,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 35"},{"q":"Which everyday test demonstrates droplet spread through a face covering?","choices":["Trying to blow out a candle while wearing one","Fogging a pair of glasses","Holding a tissue in front of the mouth","Counting breaths per minute"],"answer":0,"exp":"Correct — the candle test. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 29"},{"q":"What effect do crowded indoor environments have on disease?","choices":["They only matter for bacterial disease","They increase morbidity and mortality","They reduce transmission by dilution","They have no measurable effect"],"answer":1,"exp":"Correct — schools, daycare, nursing homes, hotels, cruise ships and hospitals. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 32"},{"q":"Which of these is named as a soil-related route of transmission?","choices":["Poorly washed produce","Swimming pools","Crowded indoor spaces","Buffets"],"answer":0,"exp":"Correct — with hands and fingernails, and pinworms in children. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 18"},{"q":"How is a fomite defined?","choices":["A person who is infected but has no symptoms","The route a pathogen takes to leave the body","A non-living surface or object","A living organism that carries disease to a host"],"answer":2,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 19"},{"q":"What does the unit CFU stand for, and why is it used?","choices":["Culture fluid unit — a measure of volume","Colony fraction unit — a proportion of the plate","Colony-forming unit","Cell freezing unit — a measure of viability"],"answer":2,"exp":"Correct. A visible colony may have started from one cell or a thousand, so the count is of colonies rather than cells. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 29"},{"q":"What complicates eradication when a pathogen can lie dormant in an intermediate host?","choices":["The animal reservoir dies out","Antibiotics become more effective","Spores and cysts persist","The pathogen mutates into a virus"],"answer":2,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 7"},{"q":"What is the reservoir of rabies?","choices":["Soil","Mammals","Birds","Fruit bats"],"answer":1,"exp":"Correct, transmitted by bite and saliva. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 8"},{"q":"Which patient group is named as being at higher risk from hospital-acquired infection?","choices":["Patients in a waiting room","The immunocompromised","Outpatients attending for blood tests","Healthy adults in primary care"],"answer":1,"exp":"Correct — with paediatric, geriatric, HIV, burns, open wound and surgical patients. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 19"},{"q":"How is rabies transmitted between humans, if at all?","choices":["Rarely, through organ transplantation","Commonly, by respiratory droplet","Commonly, by sexual contact","Never, under any circumstance"],"answer":0,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 8"},{"q":"What has driven the evolution of multi-drug resistant strains?","choices":["Shorter hospital stays","Extensive use of antibiotics","Improved hand hygiene","Antimicrobial surface coatings"],"answer":1,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 38"},{"q":"What is a PASSIVE carrier?","choices":["Not infected, but still transmits","Someone infected but without symptoms","Someone infected and symptomatic","Someone immune through prior infection"],"answer":0,"exp":"Correct — the healthcare or food worker with poor hand hygiene. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 5"},{"q":"Why is horizontal gene transfer by conjugation so significant for resistance?","choices":["It requires a bacteriophage","It only transfers chromosomal DNA","Species need not match","It only occurs between identical strains"],"answer":2,"exp":"Correct — and every daughter cell inherits the plasmid. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 45"}]};
